import icontract
from typing import List


@icontract.require(lambda offset: offset >= 0)
@icontract.ensure(lambda a, result: len(result) == len(a))
@icontract.ensure(lambda a, offset, result: all(result[i] == a[(i + offset) % len(a)] for i in range(len(a))))
def rotate(a: List[int], offset: int) -> List[int]:
    n = len(a)
    return [a[(i + offset) % n] for i in range(n)]
